using System.Text.Json.Nodes;
using System.Xml;
using Aspire.Hosting.ApplicationModel;
using Aspire.Hosting.Pipelines;
using Sheridan.Aspire.Pulumi.Azure.Base;

namespace Sheridan.Aspire.Pulumi.Azure.ServiceBus;

/// <summary>
/// An Azure Service Bus namespace provisioned by Pulumi (azure-native), mirroring the Bicep generated by
/// Aspire.Hosting.Azure.ServiceBus: a namespace (Standard SKU, local auth disabled), its queues, topics,
/// subscriptions and rules, and role assignments (default: Azure Service Bus Data Owner) for the identities of compute
/// environments hosting resources that reference the namespace or one of its entities.
/// </summary>
public sealed class AzureServiceBusResource(string name) : PulumiAzureResource(name), IResourceWithConnectionString
{
    /// <summary>Roles granted by default to anything that references the namespace (same default as the official integration).</summary>
    internal static readonly AzureServiceBusRole[] DefaultRoles = [AzureServiceBusRole.AzureServiceBusDataOwner];

    /// <summary>Namespace SKU (default Standard, as in the official integration).</summary>
    public string Sku { get; set; } = "Standard";

    /// <summary>Name of an existing namespace (set by <c>AsExisting</c>/<c>PublishAsExisting</c>); when set, the namespace itself is not created.</summary>
    public string? ExistingNamespaceName { get; internal set; }

    /// <summary>Resource group of the existing namespace (set by <c>AsExisting</c>); null means the resource group configured for this resource.</summary>
    public string? ExistingNamespaceResourceGroup { get; internal set; }

    public List<AzureServiceBusQueueResource> Queues { get; } = [];
    public List<AzureServiceBusTopicResource> Topics { get; } = [];

    private InvalidOperationException Unbound() => new($"'{Name}' has not been bound to a Pulumi stack yet; call WithPulumiStack().");

    /// <summary>Output reference to the namespace endpoint (<c>https://name.servicebus.windows.net:443/</c>).</summary>
    public PulumiOutputReference ServiceBusEndpoint => Output(Stack ?? throw Unbound(), "ServiceBusEndpoint");

    /// <summary>Output reference to the namespace host name (<c>name.servicebus.windows.net</c>).</summary>
    public PulumiOutputReference ServiceBusHostName => Output(Stack ?? throw Unbound(), "ServiceBusHostName");

    public PulumiOutputReference NameOutputReference => Output(Stack ?? throw Unbound(), "Name");

    /// <summary>The local emulator container, when <c>RunAsEmulator</c> was called (run mode only).</summary>
    public AzureServiceBusEmulatorResource? Emulator { get; internal set; }

    /// <summary>Endpoint supplied by <c>RunAsExisting</c> for local runs (run mode only); used instead of the deployed stack output.</summary>
    internal ReferenceExpression? RunEndpoint { get; set; }

    /// <summary>The namespace endpoint: the one given to <c>RunAsExisting</c> in run mode, otherwise the stack output.</summary>
    internal ReferenceExpression EndpointExpression => RunEndpoint ?? ReferenceExpression.Create($"{ServiceBusEndpoint}");

    /// <summary>The emulator connection string, the <c>RunAsExisting</c> endpoint, or the deployed namespace endpoint.</summary>
    public ReferenceExpression ConnectionStringExpression => Emulator is { } e
        ? ReferenceExpression.Create($"Endpoint=sb://{e.GetEndpoint(AzureServiceBusEmulatorResource.EndpointName).Property(EndpointProperty.HostAndPort)};SharedAccessKeyName=RootManageSharedAccessKey;SharedAccessKey=SAS_KEY_VALUE;UseDevelopmentEmulator=true;")
        : EndpointExpression;

    /// <summary>Connection string of an entity: <c>Endpoint=...;EntityPath=...</c> (the emulator form already carries <c>Endpoint=</c>).</summary>
    internal ReferenceExpression EntityConnectionString(string suffix) => Emulator is not null
        ? ReferenceExpression.Create($"{ConnectionStringExpression}{suffix}")
        : ReferenceExpression.Create($"Endpoint={EndpointExpression}{suffix}");

    /// <summary>Emits the <c>getNamespace</c> lookup (under the namespace's id) and returns the resource group the namespace and its children live in.</summary>
    internal string AddExistingLookup(PulumiProgram program, string rg)
    {
        if (ExistingNamespaceResourceGroup is null && !HasConfiguredResourceGroup)
            throw new InvalidOperationException(
                $"'{Name}' is an existing Service Bus namespace but no resource group is known. Pass resourceGroupName to AsExisting/PublishAsExisting, or call WithExistingResourceGroup/WithResourceGroup.");
        rg = ExistingNamespaceResourceGroup ?? rg;
        // The lookup variable shares the namespace's id, so ${id}.name / .id / .serviceBusEndpoint resolve as for a created namespace.
        program.Variables[Id] = new Dictionary<string, object?>
        {
            ["fn::invoke"] = new Dictionary<string, object?>
            {
                ["function"] = "azure-native:servicebus:getNamespace",
                ["arguments"] = new Dictionary<string, object?> { ["resourceGroupName"] = rg, ["namespaceName"] = ExistingNamespaceName },
            },
        };
        return rg;
    }

    protected override Task ContributeResourcesAsync(PulumiProgram program, PipelineStepContext context, string rg, string location)
    {
        if (ExistingNamespaceName is not null)
            rg = AddExistingLookup(program, rg);
        else
        // Named by the naming layer ({project}-{resource}-{stack}, normalised for ServiceBusNamespace); override with WithAzureName.
        program.AddInfraResource(Id, "azure-native:servicebus:Namespace", new()
        {
            ["type"] = "azure-native:servicebus:Namespace",
            ["properties"] = new Dictionary<string, object?>
            {
                ["namespaceName"] = NameFor(AzureNameKind.ServiceBusNamespace),
                ["resourceGroupName"] = rg,
                ["location"] = location,
                ["disableLocalAuth"] = true,
                ["publicNetworkAccess"] = "Enabled",
                ["sku"] = new Dictionary<string, object?> { ["name"] = Sku },
                ["tags"] = new Dictionary<string, object?> { ["aspire-resource-name"] = Name },
            },
        });

        Dictionary<string, object?> Child(string type, Dictionary<string, object?> props, params string[] dependsOn)
        {
            props["resourceGroupName"] = rg;
            props["namespaceName"] = $"${{{Id}.name}}";
            var d = new Dictionary<string, object?> { ["type"] = type, ["properties"] = props };
            if (dependsOn.Length > 0)
                d["options"] = new Dictionary<string, object?> { ["dependsOn"] = dependsOn.Select(x => (object?)$"${{{x}}}").ToList() };
            return d;
        }

        foreach (var q in Queues)
            program.Resources[q.PulumiId] = Child("azure-native:servicebus:Queue", q.ToProperties());

        foreach (var t in Topics)
        {
            program.Resources[t.PulumiId] = Child("azure-native:servicebus:Topic", t.ToProperties());
            foreach (var s in t.Subscriptions)
            {
                var props = s.ToProperties();
                // Reference the topic's name via the resource so Pulumi orders creation (the topic is the parent in Bicep).
                props["topicName"] = $"${{{t.PulumiId}.name}}";
                program.Resources[s.PulumiId] = Child("azure-native:servicebus:Subscription", props);
                foreach (var r in s.Rules)
                {
                    var ruleProps = r.ToProperties();
                    ruleProps["topicName"] = $"${{{t.PulumiId}.name}}";
                    ruleProps["subscriptionName"] = $"${{{s.PulumiId}.name}}";
                    program.Resources[r.PulumiId(s)] = Child("azure-native:servicebus:Rule", ruleProps);
                }
            }
        }

        program.Outputs[$"{Id}ServiceBusEndpoint"] = $"${{{Id}.serviceBusEndpoint}}";
        // split(replace(endpoint, 'https://', ''), ':')[0]  ==  select(0, split(':', select(1, split('://', endpoint))))
        program.Outputs[$"{Id}ServiceBusHostName"] = new Dictionary<string, object?>
        {
            ["fn::select"] = new List<object?>
            {
                0,
                new Dictionary<string, object?>
                {
                    ["fn::split"] = new List<object?>
                    {
                        ":",
                        new Dictionary<string, object?>
                        {
                            ["fn::select"] = new List<object?>
                            {
                                1,
                                new Dictionary<string, object?> { ["fn::split"] = new List<object?> { "://", $"${{{Id}.serviceBusEndpoint}}" } },
                            },
                        },
                    },
                },
            },
        };
        program.Outputs[$"{Id}Name"] = $"${{{Id}.name}}";
        program.Outputs[$"{Id}Id"] = $"${{{Id}.id}}";

        AddComputeRoleAssignments(program, context, $"${{{Id}.id}}");
        Provisioning.PulumiInfrastructureExtensions.ApplyInfrastructureCallbacks(this, program);
        return Task.CompletedTask;
    }

    /// <summary>Grants each compute environment's shared identity (for apps referencing the namespace or an entity) its roles on the namespace.</summary>
    private void AddComputeRoleAssignments(PulumiProgram program, PipelineStepContext ctx, string scope)
    {
        var entities = new List<IResource>();
        entities.AddRange(Queues);
        entities.AddRange(Topics);
        entities.AddRange(Topics.SelectMany(t => t.Subscriptions));

        var grants = new Dictionary<IPulumiManagedIdentityResource, HashSet<AzureServiceBusRole>>();
        foreach (var consumer in ctx.Model.GetComputeResources())
        {
            var referenced = consumer.Annotations.OfType<ResourceRelationshipAnnotation>().Select(a => a.Resource).ToList();
            if (!referenced.Contains(this) && !entities.Any(referenced.Contains)) continue;

            var custom = consumer.Annotations.OfType<AzureServiceBusRoleAnnotation>().Where(a => a.Namespace == this).ToList();
            IEnumerable<AzureServiceBusRole> roles = custom.Count > 0 ? custom.SelectMany(a => a.Roles) : DefaultRoles;
            foreach (var env in consumer.Annotations.OfType<DeploymentTargetAnnotation>()
                         .Select(a => a.ComputeEnvironment).OfType<IPulumiManagedIdentityResource>())
            {
                if (!grants.TryGetValue(env, out var set)) grants[env] = set = [];
                set.UnionWith(roles);
            }
        }

        foreach (var (env, roles) in grants)
        {
            var envId = PulumiAzureProgramExtensions.ToPulumiId(env.Name);
            foreach (var role in roles)
                program.AddRoleAssignment($"{Id}{envId}{role}", env.PrincipalIdExpression,
                    AzureServiceBusRoles.RoleDefinitionId(role), scope);
        }
    }

    /// <summary>Pulumi identifier of a child entity: the namespace's id followed by the capitalized names of the path parts.</summary>
    internal string ChildId(params string[] parts) =>
        Id + string.Concat(parts.Select(p => { var id = PulumiAzureProgramExtensions.ToPulumiId(p); return char.ToUpperInvariant(id[0]) + id[1..]; }));

    internal static string? Iso(TimeSpan? value) => value is { } v ? XmlConvert.ToString(v) : null;

    internal static void PutJson(JsonObject props, string key, object? value)
    {
        if (value is not null) props[key] = JsonValue.Create(value);
    }

    /// <summary>The emulator's <c>Config.json</c> for this namespace's queues, topics, subscriptions and rules.</summary>
    internal JsonObject ToEmulatorConfig()
    {
        var queues = new JsonArray();
        foreach (var q in Queues) queues.Add(q.ToEmulatorJson());
        var topics = new JsonArray();
        foreach (var t in Topics) topics.Add(t.ToEmulatorJson());
        return new JsonObject
        {
            ["UserConfig"] = new JsonObject
            {
                ["Namespaces"] = new JsonArray(new JsonObject { ["Name"] = Name, ["Queues"] = queues, ["Topics"] = topics }),
                ["Logging"] = new JsonObject { ["Type"] = "File" },
            },
        };
    }

    internal static void Put(Dictionary<string, object?> props, string key, object? value)
    {
        if (value is not null) props[key] = value;
    }
}

/// <summary>Roles the annotated resource's identity should get on a namespace (replaces the default).</summary>
internal sealed class AzureServiceBusRoleAnnotation(AzureServiceBusResource ns, AzureServiceBusRole[] roles) : IResourceAnnotation
{
    public AzureServiceBusResource Namespace { get; } = ns;
    public AzureServiceBusRole[] Roles { get; } = roles;
}

/// <summary>A queue in a Service Bus namespace (connection string = <c>Endpoint=...;EntityPath=queue</c>).</summary>
public sealed class AzureServiceBusQueueResource(string name, string queueName, AzureServiceBusResource parent)
    : Resource(name), IResourceWithConnectionString, IResourceWithParent<AzureServiceBusResource>
{
    public AzureServiceBusResource Parent { get; } = parent;
    public string QueueName { get; set; } = queueName;

    public bool? DeadLetteringOnMessageExpiration { get; set; }
    public TimeSpan? DefaultMessageTimeToLive { get; set; }
    public TimeSpan? DuplicateDetectionHistoryTimeWindow { get; set; }
    public string? ForwardDeadLetteredMessagesTo { get; set; }
    public string? ForwardTo { get; set; }
    public TimeSpan? LockDuration { get; set; }
    public int? MaxDeliveryCount { get; set; }
    public bool? RequiresDuplicateDetection { get; set; }
    public bool? RequiresSession { get; set; }

    internal string PulumiId => Parent.ChildId(Name);

    public ReferenceExpression ConnectionStringExpression =>
        Parent.EntityConnectionString($";EntityPath={QueueName}");

    internal JsonObject ToEmulatorJson()
    {
        var p = new JsonObject();
        AzureServiceBusResource.PutJson(p, "DeadLetteringOnMessageExpiration", DeadLetteringOnMessageExpiration);
        AzureServiceBusResource.PutJson(p, "DefaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.PutJson(p, "DuplicateDetectionHistoryTimeWindow", AzureServiceBusResource.Iso(DuplicateDetectionHistoryTimeWindow));
        AzureServiceBusResource.PutJson(p, "ForwardDeadLetteredMessagesTo", ForwardDeadLetteredMessagesTo);
        AzureServiceBusResource.PutJson(p, "ForwardTo", ForwardTo);
        AzureServiceBusResource.PutJson(p, "LockDuration", AzureServiceBusResource.Iso(LockDuration));
        AzureServiceBusResource.PutJson(p, "MaxDeliveryCount", MaxDeliveryCount);
        AzureServiceBusResource.PutJson(p, "RequiresDuplicateDetection", RequiresDuplicateDetection);
        AzureServiceBusResource.PutJson(p, "RequiresSession", RequiresSession);
        return new JsonObject { ["Name"] = QueueName, ["Properties"] = p };
    }

    internal Dictionary<string, object?> ToProperties()
    {
        var p = new Dictionary<string, object?> { ["queueName"] = QueueName };
        AzureServiceBusResource.Put(p, "deadLetteringOnMessageExpiration", DeadLetteringOnMessageExpiration);
        AzureServiceBusResource.Put(p, "defaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.Put(p, "duplicateDetectionHistoryTimeWindow", AzureServiceBusResource.Iso(DuplicateDetectionHistoryTimeWindow));
        AzureServiceBusResource.Put(p, "forwardDeadLetteredMessagesTo", ForwardDeadLetteredMessagesTo);
        AzureServiceBusResource.Put(p, "forwardTo", ForwardTo);
        AzureServiceBusResource.Put(p, "lockDuration", AzureServiceBusResource.Iso(LockDuration));
        AzureServiceBusResource.Put(p, "maxDeliveryCount", MaxDeliveryCount);
        AzureServiceBusResource.Put(p, "requiresDuplicateDetection", RequiresDuplicateDetection);
        AzureServiceBusResource.Put(p, "requiresSession", RequiresSession);
        return p;
    }
}

/// <summary>A topic in a Service Bus namespace (connection string = <c>Endpoint=...;EntityPath=topic</c>).</summary>
public sealed class AzureServiceBusTopicResource(string name, string topicName, AzureServiceBusResource parent)
    : Resource(name), IResourceWithConnectionString, IResourceWithParent<AzureServiceBusResource>
{
    public AzureServiceBusResource Parent { get; } = parent;
    public string TopicName { get; set; } = topicName;

    public TimeSpan? DefaultMessageTimeToLive { get; set; }
    public TimeSpan? DuplicateDetectionHistoryTimeWindow { get; set; }
    public bool? RequiresDuplicateDetection { get; set; }

    public List<AzureServiceBusSubscriptionResource> Subscriptions { get; } = [];

    internal string PulumiId => Parent.ChildId(Name);

    public ReferenceExpression ConnectionStringExpression =>
        Parent.EntityConnectionString($";EntityPath={TopicName}");

    internal JsonObject ToEmulatorJson()
    {
        var p = new JsonObject();
        AzureServiceBusResource.PutJson(p, "DefaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.PutJson(p, "DuplicateDetectionHistoryTimeWindow", AzureServiceBusResource.Iso(DuplicateDetectionHistoryTimeWindow));
        AzureServiceBusResource.PutJson(p, "RequiresDuplicateDetection", RequiresDuplicateDetection);
        var subs = new JsonArray();
        foreach (var s in Subscriptions) subs.Add(s.ToEmulatorJson());
        return new JsonObject { ["Name"] = TopicName, ["Properties"] = p, ["Subscriptions"] = subs };
    }

    internal Dictionary<string, object?> ToProperties()
    {
        var p = new Dictionary<string, object?> { ["topicName"] = TopicName };
        AzureServiceBusResource.Put(p, "defaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.Put(p, "duplicateDetectionHistoryTimeWindow", AzureServiceBusResource.Iso(DuplicateDetectionHistoryTimeWindow));
        AzureServiceBusResource.Put(p, "requiresDuplicateDetection", RequiresDuplicateDetection);
        return p;
    }
}

/// <summary>A subscription of a topic (connection string = <c>Endpoint=...;EntityPath=topic;SubscriptionName=sub</c>).</summary>
public sealed class AzureServiceBusSubscriptionResource(string name, string subscriptionName, AzureServiceBusTopicResource parent)
    : Resource(name), IResourceWithConnectionString, IResourceWithParent<AzureServiceBusTopicResource>
{
    public AzureServiceBusTopicResource Parent { get; } = parent;
    public string SubscriptionName { get; set; } = subscriptionName;

    public bool? DeadLetteringOnMessageExpiration { get; set; }
    public TimeSpan? DefaultMessageTimeToLive { get; set; }
    public string? ForwardDeadLetteredMessagesTo { get; set; }
    public string? ForwardTo { get; set; }
    public TimeSpan? LockDuration { get; set; }
    public int? MaxDeliveryCount { get; set; }
    public bool? RequiresSession { get; set; }

    public List<AzureServiceBusRule> Rules { get; } = [];

    internal string PulumiId => Parent.Parent.ChildId(Parent.Name, Name);

    public ReferenceExpression ConnectionStringExpression =>
        Parent.Parent.EntityConnectionString($";EntityPath={Parent.TopicName}/Subscriptions/{SubscriptionName}");

    internal JsonObject ToEmulatorJson()
    {
        var p = new JsonObject();
        AzureServiceBusResource.PutJson(p, "DeadLetteringOnMessageExpiration", DeadLetteringOnMessageExpiration);
        AzureServiceBusResource.PutJson(p, "DefaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.PutJson(p, "ForwardDeadLetteredMessagesTo", ForwardDeadLetteredMessagesTo);
        AzureServiceBusResource.PutJson(p, "ForwardTo", ForwardTo);
        AzureServiceBusResource.PutJson(p, "LockDuration", AzureServiceBusResource.Iso(LockDuration));
        AzureServiceBusResource.PutJson(p, "MaxDeliveryCount", MaxDeliveryCount);
        AzureServiceBusResource.PutJson(p, "RequiresSession", RequiresSession);
        var rules = new JsonArray();
        foreach (var r in Rules) rules.Add(r.ToEmulatorJson());
        return new JsonObject { ["Name"] = SubscriptionName, ["Properties"] = p, ["Rules"] = rules };
    }

    internal Dictionary<string, object?> ToProperties()
    {
        var p = new Dictionary<string, object?> { ["subscriptionName"] = SubscriptionName };
        AzureServiceBusResource.Put(p, "deadLetteringOnMessageExpiration", DeadLetteringOnMessageExpiration);
        AzureServiceBusResource.Put(p, "defaultMessageTimeToLive", AzureServiceBusResource.Iso(DefaultMessageTimeToLive));
        AzureServiceBusResource.Put(p, "forwardDeadLetteredMessagesTo", ForwardDeadLetteredMessagesTo);
        AzureServiceBusResource.Put(p, "forwardTo", ForwardTo);
        AzureServiceBusResource.Put(p, "lockDuration", AzureServiceBusResource.Iso(LockDuration));
        AzureServiceBusResource.Put(p, "maxDeliveryCount", MaxDeliveryCount);
        AzureServiceBusResource.Put(p, "requiresSession", RequiresSession);
        return p;
    }
}

public enum AzureServiceBusFilterType
{
    SqlFilter,
    CorrelationFilter,
}

/// <summary>A subscription rule (mirrors the official <c>AzureServiceBusRule</c>; like upstream, SQL filter expressions are not modelled).</summary>
public sealed class AzureServiceBusRule(string name)
{
    public string Name { get; set; } = name;
    public AzureServiceBusFilterType FilterType { get; set; } = AzureServiceBusFilterType.SqlFilter;
    public AzureServiceBusCorrelationFilter CorrelationFilter { get; set; } = new();

    internal string PulumiId(AzureServiceBusSubscriptionResource subscription) =>
        subscription.Parent.Parent.ChildId(subscription.Parent.Name, subscription.Name, Name);

    /// <summary>The emulator spells the filter types "Sql"/"Correlation" and a few correlation fields differently from ARM.</summary>
    internal JsonObject ToEmulatorJson() => new()
    {
        ["Name"] = Name,
        ["Properties"] = new JsonObject
        {
            ["FilterType"] = FilterType == AzureServiceBusFilterType.SqlFilter ? "Sql" : "Correlation",
            ["CorrelationFilter"] = CorrelationFilter.ToEmulatorJson(),
        },
    };

    internal Dictionary<string, object?> ToProperties()
    {
        var p = new Dictionary<string, object?> { ["ruleName"] = Name, ["filterType"] = FilterType.ToString() };
        if (FilterType == AzureServiceBusFilterType.CorrelationFilter) p["correlationFilter"] = CorrelationFilter.ToProperties();
        return p;
    }
}

/// <summary>Correlation filter of a rule (<see cref="Subject"/> maps to <c>label</c>, <see cref="SendTo"/> to <c>to</c>).</summary>
public sealed class AzureServiceBusCorrelationFilter
{
    public Dictionary<string, string> Properties { get; } = [];
    public string? CorrelationId { get; set; }
    public string? MessageId { get; set; }
    public string? SendTo { get; set; }
    public string? ReplyTo { get; set; }
    public string? Subject { get; set; }
    public string? SessionId { get; set; }
    public string? ReplyToSessionId { get; set; }
    public string? ContentType { get; set; }
    public bool? RequiresPreprocessing { get; set; }

    internal JsonObject ToEmulatorJson()
    {
        var p = new JsonObject();
        if (Properties.Count > 0)
        {
            var props = new JsonObject();
            foreach (var kv in Properties) props[kv.Key] = kv.Value;
            p["Properties"] = props;
        }
        AzureServiceBusResource.PutJson(p, "CorrelationId", CorrelationId);
        AzureServiceBusResource.PutJson(p, "MessageId", MessageId);
        AzureServiceBusResource.PutJson(p, "To", SendTo);
        AzureServiceBusResource.PutJson(p, "ReplyTo", ReplyTo);
        AzureServiceBusResource.PutJson(p, "Label", Subject);
        AzureServiceBusResource.PutJson(p, "SessionId", SessionId);
        AzureServiceBusResource.PutJson(p, "ReplyToSessionId", ReplyToSessionId);
        AzureServiceBusResource.PutJson(p, "ContentType", ContentType);
        AzureServiceBusResource.PutJson(p, "RequiresPreprocessing", RequiresPreprocessing);
        return p;
    }

    internal Dictionary<string, object?> ToProperties()
    {
        var p = new Dictionary<string, object?>();
        if (Properties.Count > 0) p["properties"] = Properties.ToDictionary(kv => kv.Key, kv => (object?)kv.Value);
        AzureServiceBusResource.Put(p, "correlationId", CorrelationId);
        AzureServiceBusResource.Put(p, "messageId", MessageId);
        AzureServiceBusResource.Put(p, "to", SendTo);
        AzureServiceBusResource.Put(p, "replyTo", ReplyTo);
        AzureServiceBusResource.Put(p, "label", Subject);
        AzureServiceBusResource.Put(p, "sessionId", SessionId);
        AzureServiceBusResource.Put(p, "replyToSessionId", ReplyToSessionId);
        AzureServiceBusResource.Put(p, "contentType", ContentType);
        AzureServiceBusResource.Put(p, "requiresPreprocessing", RequiresPreprocessing);
        return p;
    }
}

/// <summary>Service Bus built-in roles (mirrors the official <c>AzureServiceBusRole</c> / <c>ServiceBusBuiltInRole</c> data-plane roles).</summary>
public enum AzureServiceBusRole
{
    AzureServiceBusDataOwner,
    AzureServiceBusDataReceiver,
    AzureServiceBusDataSender,
}

internal static class AzureServiceBusRoles
{
    public static string RoleDefinitionId(AzureServiceBusRole role) => role switch
    {
        AzureServiceBusRole.AzureServiceBusDataOwner => "090c5cfd-751d-490a-894a-3ce6f1109419",
        AzureServiceBusRole.AzureServiceBusDataReceiver => "4f6d3b9b-027b-4f4c-9142-0e5a2a2247e0",
        AzureServiceBusRole.AzureServiceBusDataSender => "69a216fc-b8fb-44d8-bc22-1f3c2cd27a39",
        _ => throw new ArgumentOutOfRangeException(nameof(role)),
    };
}
